from datetime import datetime
from typing import Any

from config.settings import ChirpSettings
from notes.note_templates import NoteTemplate
from utils.time_utils import format_duration, format_meeting_time

DAILY_NOTES_TEMPLATE = """# Meeting Notes - {date}

{meeting_sections}

---
*Generated by Chirp*
*Total meetings: {meeting_count} | Total duration: {total_duration}*"""


class TemplateEngine:
    def __init__(self, settings: ChirpSettings):
        self.settings = settings

    def render_daily_notes(
        self,
        date: datetime,
        meeting_sections: list[str],
        meeting_count: int,
        total_duration: float,
    ) -> str:
        variables = {
            "date": date.strftime("%B %d, %Y"),
            "meeting_sections": "\n\n".join(meeting_sections),
            "meeting_count": meeting_count,
            "total_duration": format_duration(total_duration),
        }
        return _substitute_variables(DAILY_NOTES_TEMPLATE, variables)

    def render_note(self, template: NoteTemplate, data: dict[str, Any]) -> str:
        metadata = data.get("metadata", {})
        duration = metadata.get("duration_s")
        if duration is None:
            duration = metadata.get("duration") or 0

        variables: dict[str, Any] = {
            "title": data.get("title") or "Untitled Note",
            "time": _extract_meeting_time(metadata),
            "duration": format_duration(duration) if duration else "Unknown",
        }
        for section in template.sections:
            value = data.get(section.key)
            if section.kind == "prose":
                text = value.strip() if isinstance(value, str) else ""
                variables[section.key] = text or "None"
            else:
                variables[section.key] = _format_list_items(value or [])

        return _substitute_variables(template.body, variables)


def _substitute_variables(template: str, variables: dict[str, Any]) -> str:
    result = template
    for key, value in variables.items():
        result = result.replace(f"{{{key}}}", str(value))
    return result


def _format_list_items(items: list[str]) -> str:
    if not items:
        return "None"
    return "\n".join(f"- {item}" for item in items)


def _extract_meeting_time(metadata: dict[str, Any]) -> str:
    raw = metadata.get("date") or metadata.get("recorded_at")
    if isinstance(raw, datetime):
        return format_meeting_time(raw)
    if isinstance(raw, str):
        try:
            meeting_datetime = datetime.fromisoformat(raw.replace("Z", "+00:00"))
            return format_meeting_time(meeting_datetime)
        except ValueError:
            return "Unknown time"
    return "Unknown time"
